package org.brightstats.desktop;
import java.util.*;
import javafx.geometry.Insets;
import javafx.scene.control.*;
import javafx.scene.layout.VBox;
import javafx.stage.Window;
import org.brightstats.stats.*;
final class ComponentCopulaDialog {
    record Settings(String target,List<String> endogenous,CopulaRegression.Method method,CopulaRegression.PlottingPosition plottingPosition,Bootstrap.Options bootstrap){
        Settings{endogenous=List.copyOf(endogenous);Objects.requireNonNull(method);Objects.requireNonNull(plottingPosition);Objects.requireNonNull(bootstrap);if(target==null||target.isBlank()||endogenous.isEmpty()||endogenous.stream().distinct().count()!=endogenous.size())throw new IllegalArgumentException("Choose a target and distinct potentially endogenous parent names.");}
        ComponentCopula.Specification specification(ComponentScores.Model model){List<String> names=model.names();int targetIndex=names.indexOf(target);if(targetIndex<0)throw new IllegalArgumentException("Saved copula target is absent from this model.");int[] selected=endogenous.stream().mapToInt(names::indexOf).toArray();if(Arrays.stream(selected).anyMatch(i->i<0))throw new IllegalArgumentException("Saved potentially endogenous construct is absent from this model.");return new ComponentCopula.Specification(targetIndex,selected,method,plottingPosition);}
    }
    private final Dialog<Settings> dialog=new Dialog<>();private final ComboBox<String> target=new ComboBox<>();private final ListView<String> endogenous=new ListView<>();private final ComboBox<CopulaRegression.Method> method=new ComboBox<>();private final ComboBox<CopulaRegression.PlottingPosition> position=new ComboBox<>();private final ComponentScores.Model model;private Settings settings;private Bootstrap.Options bootstrap;
    private ComponentCopulaDialog(Window owner,ComponentScores.Model model,Settings previous){this.model=model;dialog.initOwner(owner);dialog.setTitle(model.estimator()+" component-score copula equation");bootstrap=previous==null?new Bootstrap.Options(1000,Bootstrap.Options.defaults().seed(),.95,BootstrapIntervals.Method.PERCENTILE,RegressionBootstrap.Convention.STANDARD,true):previous.bootstrap();List<String> names=model.names();for(int index=0;index<names.size();index++){int node=index;if(model.paths().stream().anyMatch(path->path.target()==node))target.getItems().add(names.get(index));}if(target.getItems().isEmpty())throw new IllegalArgumentException("Define a structural target with at least one parent first.");endogenous.getSelectionModel().setSelectionMode(SelectionMode.MULTIPLE);endogenous.setPrefHeight(180);target.valueProperty().addListener((observable,old,value)->parents(previous));target.setValue(previous!=null&&target.getItems().contains(previous.target())?previous.target():target.getItems().getFirst());method.getItems().setAll(CopulaRegression.Method.values());method.setValue(previous==null?CopulaRegression.Method.ORIGINAL_GAUSSIAN:previous.method());position.getItems().setAll(CopulaRegression.PlottingPosition.values());position.setValue(previous==null?CopulaRegression.PlottingPosition.WEIBULL:previous.plottingPosition());Label explanation=UiAppearance.label("Select one structural score equation. All its parents remain regressors; only selected potentially endogenous parents receive generated copula controls. Their continuity, exogeneity assumptions and distributional identification require substantive judgment. This does not silently replace the editor's other paths or total effects. Full bootstrap refits both the component and copula stages.");explanation.setWrapText(true);Label error=new Label();error.setWrapText(true);VBox content=new VBox(10,explanation,UiAppearance.label("Dependent component"),target,UiAppearance.label("Potentially endogenous parents (select one or more)"),endogenous,UiAppearance.label("Control function: ORIGINAL_GAUSSIAN or conditional two-stage 2sCOPE"),method,UiAppearance.label("Empirical plotting position"),position,error);content.setPadding(new Insets(12));content.setPrefWidth(680);dialog.getDialogPane().setContent(content);dialog.getDialogPane().getButtonTypes().setAll(ButtonType.OK,ButtonType.CANCEL);dialog.getDialogPane().lookupButton(ButtonType.OK).addEventFilter(javafx.event.ActionEvent.ACTION,event->{settings=null;try{settings=new Settings(target.getValue(),List.copyOf(endogenous.getSelectionModel().getSelectedItems()),method.getValue(),position.getValue(),bootstrap);var specification=settings.specification(model);long parents=model.paths().stream().filter(path->path.target()==specification.target()).map(PlsSem.Edge::source).distinct().count();if(method.getValue()==CopulaRegression.Method.TWO_STAGE_GAUSSIAN&&parents==specification.endogenous().length)throw new IllegalArgumentException("Two-stage correction needs at least one unselected exogenous parent.");}catch(Exception problem){settings=null;event.consume();error.setText(problem.getMessage());}});dialog.setResultConverter(button->button==ButtonType.OK?settings:null);}
    private void parents(Settings previous){int targetIndex=model.names().indexOf(target.getValue());endogenous.getItems().setAll(model.paths().stream().filter(path->path.target()==targetIndex).map(PlsSem.Edge::source).distinct().sorted().map(model.names()::get).toList());if(previous!=null&&previous.target().equals(target.getValue()))for(String name:previous.endogenous())if(endogenous.getItems().contains(name))endogenous.getSelectionModel().select(name);if(endogenous.getSelectionModel().isEmpty()&&!endogenous.getItems().isEmpty())endogenous.getSelectionModel().selectFirst();}
    static Optional<Settings> show(Window owner,ComponentScores.Model model,Settings previous,boolean resampling){var test=new ComponentCopulaDialog(owner,model,previous);var selection=test.dialog.showAndWait();if(selection.isEmpty()||!resampling)return selection;var choice=BootstrapDialog.show(owner,selection.get().bootstrap());if(choice.isEmpty())return Optional.empty();var selected=selection.get();return Optional.of(new Settings(selected.target(),selected.endogenous(),selected.method(),selected.plottingPosition(),choice.get()));}
    static Settings smokeTest(Window owner,ComponentScores.Model model){var test=new ComponentCopulaDialog(owner,model,null);test.dialog.show();Button ok=(Button)test.dialog.getDialogPane().lookupButton(ButtonType.OK);test.endogenous.getSelectionModel().clearSelection();ok.fire();if(!test.dialog.isShowing()||test.settings!=null)throw new AssertionError("Empty endogenous selection accepted");test.endogenous.getSelectionModel().selectAll();test.method.setValue(CopulaRegression.Method.TWO_STAGE_GAUSSIAN);ok.fire();if(!test.dialog.isShowing()||test.settings!=null)throw new AssertionError("Two-stage correction without exogenous parent accepted");test.endogenous.getSelectionModel().clearSelection();test.endogenous.getSelectionModel().selectFirst();ok.fire();if(test.dialog.getResult()==null)throw new AssertionError("Valid component copula selection rejected");var result=test.dialog.getResult();return new Settings(result.target(),result.endogenous(),result.method(),result.plottingPosition(),new Bootstrap.Options(40,4561,.95));}
}
